/* ===== MINI-GAME: Steady the Flame (first-contact-hope) ===== */
const MG_INSTRUCTOR_LINE='You hold the flame steady, and those who approach decide whether to trust you.';
const MG={active:false,shown_tip:false,t:0,flame:0.5,target:0.5,target_drift_t:0,nomads:[],won:false,failed:false,fail_type:null,entry_t:0,exit_t:0};
function mgInit(st=MG){st.active=false;st.shown_tip=false;st.t=0;st.flame=0.5;st.target=0.5;st.target_drift_t=0;st.nomads=[];st.won=false;st.failed=false;st.fail_type=null;st.entry_t=0;st.exit_t=0;}
function mgArm(st=MG){if(st.active)return;mgInit(st);st.active=true;st.entry_t=0;const ang=Math.PI*2/8;for(let i=0;i<8;i++){const a=i*ang;st.nomads.push({a:a,r:180,commit:0.5,alive:true});}}
function mgStep(st,clicked,dt=1){if(st.won||st.failed)return st;st.t+=dt;if(st.entry_t<48){st.entry_t+=dt;return st;}const DECAY=0.0008,CLICK_BOOST=0.12,STEADY_LO=0.42,STEADY_HI=0.58,FLARE=0.75,DIM=0.25;if(clicked)st.flame=Math.min(1,st.flame+CLICK_BOOST);st.flame=Math.max(0,st.flame-DECAY*dt);st.target_drift_t+=dt;if(st.target_drift_t>120){st.target_drift_t=0;st.target=0.45+Math.random()*0.1;}const steady=st.flame>=STEADY_LO&&st.flame<=STEADY_HI&&Math.abs(st.flame-st.target)<0.15;let all_close=true,any_alive=false;for(const n of st.nomads){if(!n.alive)continue;any_alive=true;if(steady){n.commit=Math.min(1,n.commit+0.004*dt);n.r=Math.max(40,n.r-0.15*dt);}else if(st.flame>FLARE){n.commit=Math.max(0,n.commit-0.012*dt);n.r=Math.min(180,n.r+0.4*dt);if(n.commit<0.1)n.alive=false;}else if(st.flame<DIM){n.commit=Math.max(0,n.commit-0.008*dt);n.r=Math.min(180,n.r+0.25*dt);if(n.commit<0.15)n.alive=false;}else{n.commit=Math.max(0,n.commit-0.002*dt);n.r=Math.min(180,n.r+0.05*dt);}if(n.r>50)all_close=false;}if(!any_alive){st.failed=true;st.fail_type=st.flame>FLARE?'bright':'dim';st.exit_t=0;}else if(all_close&&any_alive){let min_c=1;for(const n of st.nomads)if(n.alive&&n.commit<min_c)min_c=n.commit;if(min_c>0.85){st.won=true;st.exit_t=0;}}if(st.t>600&&!st.won&&!st.failed){st.failed=true;st.fail_type='timeout';st.exit_t=0;}return st;}
function mgResolve(st){if(!st.won&&!st.failed)return null;if(st.won){const alive=st.nomads.filter(n=>n.alive).length;if(alive>=6)return'convert_devout';if(alive>=3)return'convert_devout';return'no_effect';}if(st.fail_type==='bright')return'drift_apathy';if(st.fail_type==='dim')return'burnout';return'no_effect';}
if(location.hash.includes('mg')){const _origNG=newGame;newGame=function(pole){_origNG(pole);mgArm();};}

