// M1: flame brightness responds to clicks and decays
{const s={};mgInit(s);mgArm(s);s.entry_t=48;const f0=s.flame;mgStep(s,true,1);const f1=s.flame;mgStep(s,false,100);const f2=s.flame;const rose=f1>f0,fell=f2<f1;out.push(['M1 flame rises on click, decays over time',rose&&fell,`${f0.toFixed(2)}->${f1.toFixed(2)}->${f2.toFixed(2)}`]);}
// M2: nomads approach when flame is steady
{const s={};mgInit(s);mgArm(s);s.entry_t=48;s.flame=0.5;s.target=0.5;const r0=s.nomads[0].r;for(let i=0;i<200;i++)mgStep(s,false,1);const r1=s.nomads[0].r;out.push(['M2 nomads approach when flame steady',r1<r0&&r1<100,`r ${r0.toFixed(1)}->${r1.toFixed(1)}`]);}
// M3: win condition triggers when ring closes
{const s={};mgInit(s);mgArm(s);s.entry_t=48;s.flame=0.5;s.target=0.5;for(const n of s.nomads){n.r=45;n.commit=0.9;}mgStep(s,false,1);out.push(['M3 win triggers when nomads close and committed',s.won,`won=${s.won}`]);}
